// Original vector artwork, drawn as reusable pieces so the comic can move.
const ink = '#252328';
const star = (x,y,s=1,c='#ffdc52') => `<path transform="translate(${x} ${y}) scale(${s})" d="M0 -24 8 -8 25 -7 13 6 17 24 0 15 -17 24 -13 6 -25 -7 -8 -8Z" fill="${c}" stroke="${ink}" stroke-width="3" stroke-linejoin="round"/>`;
const cloud = (x,y,s=1) => `<path transform="translate(${x} ${y}) scale(${s})" d="M0 30 Q-15 4 12 1 Q16 -26 43 -14 Q65 -35 82 -9 Q113 -10 111 14 Q143 30 112 39H12Z" fill="#fff8e9" stroke="${ink}" stroke-width="3"/>`;
export function character(who,x=0,y=0,s=1,pose='happy') {
 const face = `<ellipse cx="-15" cy="-9" rx="3.7" ry="5" fill="${ink}"/><ellipse cx="15" cy="-9" rx="3.7" ry="5" fill="${ink}"/>${pose==='sad'?'<path d="M-8 9Q0 0 8 9" fill="none"/>':'<path d="M-8 4Q0 17 9 3" fill="none"/>'}<ellipse cx="-24" cy="2" rx="7" ry="4" fill="#f79d96" stroke="none"/><ellipse cx="25" cy="2" rx="7" ry="4" fill="#f79d96" stroke="none"/>`;
 const limbs = `<path d="M-22 36 -29 60 -43 61M20 36 29 60 44 60" fill="none" stroke-width="6"/><path d="M-39 0Q-60 15 -68 -4M40 1Q56 20 69 -3" fill="none" stroke-width="5" stroke-linecap="round"/>`;
 let body='';
 if(who==='pip') body=`${limbs}<path d="M-36 -35 -25 -67 0 -88 26 -67 37 -35 35 37Q0 49 -36 36Z" fill="#ffcb4e"/><path d="M-25 -67 0 -88 26 -67Z" fill="#ff8c6a"/><path d="M-12 -78 0 -88 13 -78Z" fill="${ink}"/><path d="M-37 -34H36V24H-36Z" fill="#ff8c6a"/><path d="M-31 -27H30M-30 17H29" fill="none" stroke-width="2"/><g transform="translate(0 -3)">${face}</g><path d="M-28 28 0 32 29 28" fill="none" stroke-width="2"/>`;
 if(who==='blob') body=`${limbs}<path d="M-48 33Q-65 11 -46 -11Q-49 -44 -20 -40Q-8 -68 14 -44Q44 -48 42 -20Q70 -3 49 17Q53 44 29 44H-25Q-43 48 -48 33Z" fill="#a79fe4"/>${face}<path d="M-30 -24Q-30 -35 -17 -32" fill="none" stroke="#d8d2ff" stroke-width="5"/>`;
 if(who==='zip') body=`${limbs}<path d="M-38 -35Q0 -53 39 -35L35 37Q0 49 -36 36Z" fill="#65c7bb"/><path d="M-38 -35Q0 -60 39 -35Q39 -17 0 -17T-38 -35Z" fill="#ffedab"/><ellipse cx="0" cy="-35" rx="16" ry="8" fill="#fff7e7"/><g transform="translate(0 13)">${face}</g><path d="M35 10 59 35 40 45 20 19" fill="#65c7bb"/>`;
 if(who==='rub') body=`${limbs}<path d="M-43 -49 26 -58 48 -39 39 39 -31 48 -49 27Z" fill="#f59dbb"/><path d="M-43 -49 26 -58 48 -39 -25 -29Z" fill="#ffd7e5"/><path d="M-49 8 -25 26 42 17 39 39 -31 48 -49 27Z" fill="#84cdd1"/><g transform="translate(-1 -6)">${face}<path d="M-23 -20 -9 -16M8 -17 23 -22" fill="none"/></g><path d="M-25 -29 -31 48" fill="none" stroke-width="2"/>`;
 return `<g transform="translate(${x} ${y}) scale(${s})" stroke="${ink}" stroke-width="3.8" stroke-linejoin="round" stroke-linecap="round">${body}</g>`;
}
function house(x,y,w,h,color,kind=0) {return `<g transform="translate(${x} ${y})"><path d="M0 0V-${h}L${w/2} -${h+34} ${w} -${h}V0Z" fill="${color}" stroke="${ink}" stroke-width="3"/><path d="M-8 -${h} ${w/2} -${h+39} ${w+8} -${h}" fill="none" stroke="${ink}" stroke-width="5"/><rect x="${w/2-13}" y="-40" width="26" height="40" rx="12" fill="#fff4d9" stroke="${ink}" stroke-width="3"/>${[17,w-33].map(xx=>`<rect x="${xx}" y="-${h-19}" width="16" height="21" rx="3" fill="#fff4d9" stroke="${ink}" stroke-width="2"/>`).join('')}${kind?`<path d="M-5 -60H${w+5}L${w} -79H0Z" fill="#f289aa" stroke="${ink}" stroke-width="3"/>`:''}</g>`;}
function sign(txt,x,y,rot=0) {return `<g transform="translate(${x} ${y}) rotate(${rot})"><path d="M0 18V74" stroke="${ink}" stroke-width="6"/><rect x="-70" y="-16" width="140" height="40" rx="4" fill="#ffdd5b" stroke="${ink}" stroke-width="3"/><text y="10" text-anchor="middle" font-size="15" font-weight="900" font-family="Arial, sans-serif" fill="${ink}">${txt}</text></g>`;}
function balloon(txt,x,y,w=175) { const lines=txt.split('|');return `<g class="bubble" transform="translate(${x} ${y})"><path d="M12 0H${w-12}Q${w} 0 ${w} 14V${lines.length*21+14}Q${w} ${lines.length*21+27} ${w-13} ${lines.length*21+27}H42L25 ${lines.length*21+46} 28 ${lines.length*21+27}H12Q0 ${lines.length*21+27} 0 ${lines.length*21+14}V14Q0 0 12 0Z" fill="#fffdf5" stroke="${ink}" stroke-width="3"/>${lines.map((line,i)=>`<text x="${w/2}" y="${26+i*21}" text-anchor="middle" font-family="Arial, sans-serif" font-weight="900" font-size="16" fill="${ink}">${line}</text>`).join('')}</g>`;}
export function art(scene='cover',opts={}) {
 const {gray=false,bubble='',companion='blob',ending=''}=opts;
 let bg='#b8e5d7',set='',actors='',sky='';
 const hills=`<path d="M-40 325Q110 230 256 324Q420 220 680 325V480H-40Z" fill="#8fc996" stroke="${ink}" stroke-width="3"/><path d="M-20 387Q160 324 300 386Q490 307 660 380V480H-20Z" fill="#d1d987" stroke="${ink}" stroke-width="3"/>`;
 if(['cover','town','festival','ending'].includes(scene)) {
 sky=`${cloud(52,71,.68)}${cloud(400,50,.8)}<circle cx="542" cy="81" r="34" fill="#ffda54" stroke="${ink}" stroke-width="3"/><path d="M542 31V20M542 131V140M492 81H481M592 81H605M506 45 497 37M580 116 587 124" stroke="${ink}" stroke-width="3"/>`;
 set=`${hills}${house(18,340,94,112,'#eaaaaf',1)}${house(120,322,83,153,'#f5d765')}${house(424,332,86,116,'#a1a9df',1)}${house(523,344,97,152,'#f7a273')}<path d="M260 480 305 320 350 320 428 480" fill="#f8eac7" stroke="${ink}" stroke-width="3"/><path d="M48 158Q310 253 589 147" fill="none" stroke="${ink}" stroke-width="2"/>${[85,139,195,253,311,369,427,485,540].map((x,i)=>`<path d="M${x} ${177+Math.sin(i/8*Math.PI)*26}l16 28 13 -24Z" fill="${['#ff94af','#ffda54','#a99ee3'][i%3]}" stroke="${ink}" stroke-width="2"/>`).join('')}`;
 actors=`<g class="float-a">${character('pip',275,350,1.12)}</g><g class="float-b">${character('blob',414,380,.85)}</g><g class="float-c">${character('zip',158,382,.79)}</g>`;
 if(scene==='cover') {actors+=`<g transform="translate(493 230) rotate(12)">${character('rub',0,0,.66,'sad')}</g>`;sky+=`${star(78,242,.8,'#ffdd55')}${star(564,400,.7,'#ee91b6')}<g transform="translate(319 111) rotate(-9)"><path d="M-63 -28 -28 -22 -19 -48 0 -26 29 -40 32 -15 64 -18 46 7 65 29 31 28 26 51 3 32 -26 45 -28 22 -62 25 -42 0Z" fill="#ffdb52" stroke="${ink}" stroke-width="3"/><text text-anchor="middle" y="10" font-family="Arial, sans-serif" font-weight="900" font-size="31" fill="${ink}">POOF!</text></g>`;}
 if(scene==='ending') { actors=character('pip',229,350,1.15)+character('blob',372,380,.9)+character('zip',126,377,.8)+character('rub',502,356,1,ending==='loop'?'sad':'happy');sky+=Array.from({length:18},(_,i)=>`<path d="M${27+i*34} ${30+(i*47)%210}l6 12" stroke="${['#f47aa4','#ffda54','#8b82cd'][i%3]}" stroke-width="5"/>`).join('');}
 } else if(scene==='bridge') {
 bg='#d4d8ef';sky=cloud(54,60,.9)+cloud(405,90,.85);set=`<path d="M0 312Q100 285 183 340T375 340T650 315V480H0" fill="#74baca" stroke="${ink}" stroke-width="3"/><path d="M0 300 150 278 181 345 0 394Z" fill="#9bc688" stroke="${ink}" stroke-width="3"/><path d="M460 277 650 293V393L425 344Z" fill="#9bc688" stroke="${ink}" stroke-width="3"/><path d="M132 278Q300 354 471 276M132 337Q300 418 471 337" fill="none" stroke="${ink}" stroke-width="6"/>${Array.from({length:12},(_,i)=>`<path d="M${143+i*28} ${292+Math.sin(i/11*Math.PI)*35}v55" stroke="#e7b377" stroke-width="19"/><path d="M${143+i*28} ${292+Math.sin(i/11*Math.PI)*35}v55" stroke="${ink}" stroke-width="2"/>`).join('')}${sign('MAYBE BRIDGE',330,165,-4)}<path d="M80 429q30 -15 60 0m210 3q30 -15 60 0m80 -40q30 -15 60 0" fill="none" stroke="#eaf8ee" stroke-width="4"/>`;actors=character('pip',165,289,.9)+character(companion,464,303,1.05);
 } else if(scene==='market') {
 bg='#f9c9d7';sky=cloud(53,49,.7)+cloud(448,61,.8);set=`<path d="M0 330Q300 280 640 340V480H0" fill="#ebc7a0" stroke="${ink}" stroke-width="3"/><path d="M48 140H292V338H48Z" fill="#fff1bd" stroke="${ink}" stroke-width="3"/><path d="M30 141H311L285 87H57Z" fill="#81c5c0" stroke="${ink}" stroke-width="3"/>${[56,107,158,209,260].map(x=>`<path d="M${x} 87l-8 54h27l6 -54Z" fill="#fff2cf"/>`).join('')}<rect x="64" y="214" width="212" height="66" rx="4" fill="#a89cdb" stroke="${ink}" stroke-width="3"/><text x="170" y="180" font-family="Arial" text-anchor="middle" font-weight="900" font-size="21" fill="${ink}">LOST &amp; FOUND</text>${sign('NO REFUNDS*',497,198,5)}${star(98,242,.6)}<circle cx="168" cy="244" r="17" fill="#f29cae" stroke="${ink}" stroke-width="2"/><path d="M221 263 230 224 250 255Z" fill="#85cfbd" stroke="${ink}" stroke-width="2"/>`;actors=character('pip',342,368,1.05)+character('zip',163,346,.91)+character('blob',496,379,.8);
 } else if(scene==='library') {
 bg='#b9c0e3';set=`<path d="M0 362H640V480H0" fill="#dba982" stroke="${ink}" stroke-width="3"/>${[38,244,450].map((x,i)=>`<rect x="${x}" y="62" width="150" height="281" rx="65" fill="#fff0cb" stroke="${ink}" stroke-width="4"/>${[150,227,302].map((y,j)=>`<path d="M${x+7} ${y}H${x+143}" stroke="${ink}" stroke-width="5"/>${Array.from({length:6},(_,k)=>`<rect x="${x+17+k*20}" y="${y-47-(k%2)*13}" width="15" height="${47+(k%2)*13}" rx="2" fill="${['#ed98b3','#86c9b8','#e8c45b'][(k+i+j)%3]}" stroke="${ink}" stroke-width="2"/>`).join('')}`).join('')}`).join('')}<path d="M212 480 243 348H400L441 480" fill="#ee9eaf" stroke="${ink}" stroke-width="3"/>`;actors=character('pip',254,352,1)+character(companion,420,375,.9);sky=`<text x="322" y="40" text-anchor="middle" fill="${ink}" font-family="Arial" font-weight="900" font-size="16">THE LIBRARY OF ALMOST-IDEAS</text>`;
 } else if(scene==='tower') {
 bg='#c8bfdf';sky=cloud(35,96,.7)+cloud(460,62,.9);set=`<path d="M0 380Q320 292 640 380V480H0" fill="#9cb9b2" stroke="${ink}" stroke-width="3"/><path d="M210 355 230 100H425L449 355Z" fill="#e9c6b9" stroke="${ink}" stroke-width="4"/><path d="M220 100 245 65H412L437 100Z" fill="#8b86ae" stroke="${ink}" stroke-width="3"/><path d="M270 354V267Q330 202 387 267V354Z" fill="#686984" stroke="${ink}" stroke-width="4"/><circle cx="332" cy="165" r="40" fill="#ffedc1" stroke="${ink}" stroke-width="4"/><path d="M332 135V165L352 178" fill="none" stroke="${ink}" stroke-width="5"/>${sign('DO NOT DOODLE',115,228,-5)}<path d="M253 355 195 480H490L410 355Z" fill="#e6d9bc" stroke="${ink}" stroke-width="3"/>`;actors=character('pip',260,381,.95)+character(companion,412,397,.85);
 } else { // Inside the eraser's wonderfully impractical machine.
 bg='#a6c7c9';set=`<path d="M0 355H640V480H0" fill="#d2c2a3" stroke="${ink}" stroke-width="3"/><rect x="87" y="85" width="467" height="251" rx="24" fill="#ded6e6" stroke="${ink}" stroke-width="5"/><path d="M130 87V40H232V87M438 87V38H483V87" fill="#8e9da8" stroke="${ink}" stroke-width="5"/><rect x="130" y="125" width="220" height="104" rx="12" fill="#86839d" stroke="${ink}" stroke-width="4"/><path d="M150 174h20l15 -27 22 58 22 -53 21 39 20 -17h55" fill="none" stroke="#f9d36d" stroke-width="5"/><circle cx="441" cy="173" r="46" fill="#f3acbf" stroke="${ink}" stroke-width="4"/><path d="M417 171H465M441 148V197" stroke="${ink}" stroke-width="6"/><circle cx="157" cy="273" r="13" fill="#ef926e" stroke="${ink}" stroke-width="3"/><circle cx="206" cy="273" r="13" fill="#86cbb1" stroke="${ink}" stroke-width="3"/><circle cx="255" cy="273" r="13" fill="#f0ce59" stroke="${ink}" stroke-width="3"/><path d="M395 266H490" stroke="${ink}" stroke-width="8"/>`;actors=character('pip',222,371,1)+character('rub',443,366,1.13,scene==='machine'?'sad':'happy');
 }
 const textBubble=bubble?balloon(bubble,scene==='cover'?30:255,scene==='library'?85:36,scene==='cover'?190:225):'';
 return `<svg viewBox="0 0 640 480" xmlns="http://www.w3.org/2000/svg" role="img" aria-label="Illustrated ${scene==='cover'?'Doodleburg, a colorful town of living art supplies':scene+' scene with Pip and friends'}"><defs><pattern id="dots" width="10" height="10" patternUnits="userSpaceOnUse"><circle cx="2" cy="2" r="1" fill="${ink}" opacity=".07"/></pattern><filter id="gray"><feColorMatrix type="saturate" values="0.12"/></filter></defs><g ${gray?'filter="url(#gray)"':''}><path fill="${bg}" d="M0 0H640V480H0Z"/><path fill="url(#dots)" d="M0 0H640V480H0Z"/>${sky}${set}${gray?actors:""}</g>${gray?"":`<g class="scene-actors">${actors}</g>`}${textBubble}<path d="M29 443q8 -18 15 0m495 9q9 -18 17 0" stroke="${ink}" stroke-width="3" fill="none"/></svg>`;
}
